interface Chargeable {double chargingFee(int units);} abstract class Vehicle {abstract double parkingFee(int hours);} class EV extends Vehicle implements Chargeable {double parkingFee(int h){return h*25;} public double chargingFee(int u){return u*8;}} public class Main {public static void main(String[]a){EV e=new EV();System.out.println("Parking="+e.parkingFee(2)+", charging="+e.chargingFee(5));}}
